// Explicit schematic fallback; never presented as the 3D renderer.
import {bobberPos} from './fishing.js';
export class FallbackWorld{
constructor(root){this.canvas=document.createElement('canvas');root.append(this.canvas);this.ctx=this.canvas.getContext('2d');this.renderer={domElement:this.canvas};this.resize=()=>{this.canvas.width=innerWidth;this.canvas.height=innerHeight;};addEventListener('resize',this.resize);this.resize();const note=document.createElement('div');note.textContent='MODO 2D · WebGL indisponível neste navegador';note.className='fallback-note';document.body.append(note);}
quality(){}ripple(){}
update(dt,t,b,s,fish,shark){const c=this.ctx,w=this.canvas.width,h=this.canvas.height;const gradient=c.createLinearGradient(0,0,0,h);gradient.addColorStop(0,'#557d87');gradient.addColorStop(.35,'#254f5d');gradient.addColorStop(1,'#133b46');c.fillStyle=gradient;c.fillRect(0,0,w,h);c.strokeStyle='#9bbfbd20';c.lineWidth=1;for(let y=0;y<h;y+=20){c.beginPath();for(let x=0;x<=w;x+=8){const yy=y+Math.sin(x*.018+t+y)*3;c.lineTo(x,yy);}c.stroke();}const scale=3,cx=w*.53,cy=h*.53;let coast=cy+(45-b.z)*scale;if(coast<h){c.fillStyle='#526859';c.beginPath();c.moveTo(0,coast+30);for(let x=0;x<w;x+=10)c.lineTo(x,coast+Math.sin(x*.01)*18);c.lineTo(w,h);c.lineTo(0,h);c.fill();c.fillStyle='#867257';c.fillRect(cx-b.x*scale-12,cy+(8-b.z)*scale,24,100);for(let i=0;i<9;i++){const x=cx+(-100+i*22-b.x)*scale,y=coast+40+Math.sin(i)*15;c.fillStyle='#c5baa0';c.fillRect(x,y,28,25);c.fillStyle='#6f5041';c.beginPath();c.moveTo(x-4,y);c.lineTo(x+14,y-15);c.lineTo(x+32,y);c.fill();}}
const bt=Math.max(s.upgrades.hull||0,s.upgrades.motor||0,s.upgrades.hold||0),rt=s.upgrades.rod||0;
c.save();c.translate(cx,cy);c.rotate(-b.angle);c.fillStyle='#19343b88';c.beginPath();c.ellipse(6,6,22+bt*2,45+bt*3,0,0,7);c.fill();c.fillStyle=['#6ba69a','#4d8ec4','#e8f1f8','#1f496e'][bt];c.strokeStyle=['#d4c9a3','#f2ead7','#ffffff','#f5c85c'][bt];c.lineWidth=3+bt*.5;c.beginPath();c.moveTo(0,-42-bt*3);c.quadraticCurveTo(26+bt*2,-20,19+bt,36);c.lineTo(-19-bt,36);c.quadraticCurveTo(-26-bt*2,-20,0,-42-bt*3);c.fill();c.stroke();c.fillStyle='#355859';c.fillRect(-15,-12,30,5);c.fillRect(-15,18,30,5);if(bt>=1){c.fillStyle='#8cd9ee88';c.fillRect(-10,-8,20,6);}if(bt>=2){c.strokeStyle=bt>=3?'#f5c85c':'#dbe4e8';c.lineWidth=2;c.strokeRect(-14,-16,28,34);}if(bt>=3){c.fillStyle='#f5c85c';c.beginPath();c.arc(0,-42,4,0,7);c.fill();}c.fillStyle='#d1c3a0';c.beginPath();c.arc(0,3,8,0,7);c.fill();c.strokeStyle=['#b5925b','#226888','#d99b26','#6cf5ff'][rt];c.lineWidth=2+rt*.7;c.beginPath();c.moveTo(4,2);c.lineTo(24+rt*4,-18-rt*3);c.stroke();c.restore();if(fish.state!=='idle'){c.strokeStyle=rt>=3?'#6cf5ff':'#ced7b8';c.lineWidth=1+rt*.3;c.beginPath();const bp=bobberPos(b,fish.castDistance),k=fish.castT??1,ex=cx+5+((bp.x-b.x)*scale-5)*k,ey=cy+(bp.z-b.z)*scale*k;c.moveTo(cx+5,cy);c.lineTo(ex,ey);c.stroke();c.fillStyle=['#df9d68','#52b6e8','#f2c14e','#6cf5ff'][rt];c.beginPath();c.arc(ex,ey+Math.sin(t*(fish.state==='bite'?14:3))*3,4+rt*.5,0,7);c.fill();}if(shark.state!=='away'){c.save();c.translate(cx+shark.distance*scale,cy-shark.distance*scale);c.fillStyle='#19313b';c.beginPath();c.moveTo(-13,10);c.lineTo(0,-20);c.lineTo(9,10);c.fill();c.restore();}}
}
